const fs = require('node:fs/promises');
const path = require('node:path');

const ENDPOINT = 'http://127.0.0.1:63961/status';
const OUTPUT = path.join(__dirname, 'results', 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  const body = await res.json();

  await fs.mkdir(path.dirname(OUTPUT), { recursive: true });
  await fs.writeFile(OUTPUT, JSON.stringify({ status: body.status }) + '\n');

  console.log(`status=${body.status} -> ${OUTPUT}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

